-- SEO audit follow-up: accurate privacy copy and removal of unsupported seeded claims.
-- Existing page revision triggers preserve snapshots; custom edits are not replaced wholesale.
update public.pages set body_html = body_html || E'\n' || '<h2 id="campaign-attribution">Campaign attribution and browser storage</h2><p>When a website link includes campaign tags (utm_source, utm_medium, utm_campaign, utm_term or utm_content) or click identifiers (gclid or fbclid), we keep those values and the landing-page path in this tab’s sessionStorage under oqc-campaign. This helps our team understand which tagged campaigns led to an enquiry. We do not create a visitor ID or send these values to an advertising platform from this website.</p><p>Browser attribution is used for up to 24 hours after the most recent tagged visit and is normally cleared when the tab closes. An expired entry is removed the next time attribution is checked. A new tagged visit replaces the earlier campaign. Forms still work when this browser storage is blocked.</p><p>If you submit an enquiry, campaign details are included with that enquiry for staff reporting. The 24-hour browser limit does not delete a submitted enquiry from our records. You can contact us to ask about access, correction or deletion of your enquiry data.</p>'
where slug='privacy-policy' and locale='en' and deleted_at is null
and position('id="campaign-attribution"' in body_html)=0;
update public.pages set body_html = replace(replace(body_html, '<p>Online Quran College started in 2018 with a small group of certified teachers and one goal: to bridge traditional Islamic education with modern, interactive virtual classrooms. Today we teach children and adults across the UK, the USA, Canada, Australia, Europe and beyond — always one-to-one, always live.</p>', '<p>Online Quran College offers live one-to-one online lessons for children and adults. Explore Quran reading, Tajweed, memorisation and Arabic courses, and discuss your learning goals and preferred schedule with the college.</p>'), '<p>Our teachers hold formal qualifications in Islamic studies and Quranic recitation, and recite with correct Tajweed. Every teacher goes through a background check and a teaching-skills evaluation, and receives regular coaching on online teaching and working with children.</p>', '<p>Before choosing a teacher, ask our team about the qualifications, teaching experience and languages relevant to your course. Parents can also ask about supervision, safeguarding arrangements and how concerns are handled.</p>')
where slug='about' and locale='en' and deleted_at is null
and (position('<p>Online Quran College started in 2018 with a small group of certified teachers and one goal: to bridge traditional Islamic education with modern, interactive virtual classrooms. Today we teach children and adults across the UK, the USA, Canada, Australia, Europe and beyond — always one-to-one, always live.</p>' in body_html)>0 or position('<p>Our teachers hold formal qualifications in Islamic studies and Quranic recitation, and recite with correct Tajweed. Every teacher goes through a background check and a teaching-skills evaluation, and receives regular coaching on online teaching and working with children.</p>' in body_html)>0);
update public.settings set value='[{"value": "Online", "label": "Learn from home"}, {"value": "All ages", "label": "Children & adults"}, {"label": "Live classes", "value": "1-on-1"}, {"label": "Flexible timings", "value": "24/7"}]'::jsonb where key='site.stats' and value='[{"label": "Teaching since", "value": "2018"}, {"label": "Students learning", "value": "600+"}, {"label": "Live classes", "value": "1-on-1"}, {"label": "Flexible timings", "value": "24/7"}]'::jsonb;
update public.settings set value=jsonb_set(value, '{established}', '""'::jsonb)
where key='site.identity' and value->>'established'='2018';
insert into public.pages (slug,title,excerpt,body_html,canonical_url,status,published_at) values ('locations-united-kingdom-bradford', 'Online Quran classes in Bradford, United Kingdom', 'Plan online Quran lessons from Bradford. Check local scheduling, explore courses and request approved GBP fees.', '<h2>Preparing for online Quran lessons in Bradford</h2><p>Share your learner’s age group, reading level and goals with the college. Use the local-time planner on this page before suggesting lesson times. Ask for approved GBP fees and confirm teacher availability before enrolling.</p><p>Lessons take place online. This page does not represent a physical branch in Bradford.</p>', '/locations/united-kingdom/bradford','published',now()) on conflict (slug,locale) do nothing;
insert into public.pages (slug,title,excerpt,body_html,canonical_url,status,published_at) values ('locations-united-kingdom-leicester', 'Online Quran classes in Leicester, United Kingdom', 'Plan online Quran lessons from Leicester. Check local scheduling, explore courses and request approved GBP fees.', '<h2>Preparing for online Quran lessons in Leicester</h2><p>Share your learner’s age group, reading level and goals with the college. Use the local-time planner on this page before suggesting lesson times. Ask for approved GBP fees and confirm teacher availability before enrolling.</p><p>Lessons take place online. This page does not represent a physical branch in Leicester.</p>', '/locations/united-kingdom/leicester','published',now()) on conflict (slug,locale) do nothing;
